1	package skill
2	
3	import (
4		"errors"
5		"fmt"
6		"io/fs"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11	
12		"github.com/DocumentDrivenDX/fizeau/internal/safefs"
13	)
14	
15	// Skill describes a single discovered SKILL.md file.
16	type Skill struct {
17		// Path is the absolute filesystem path to the SKILL.md file.
18		Path string
19		// Frontmatter is the parsed YAML metadata.
20		Frontmatter Frontmatter
21		// BodyOffset is the byte offset at which the markdown body begins
22		// (i.e. the byte immediately after the closing `---` line).
23		BodyOffset int64
24	}
25	
26	// Name returns the skill's frontmatter name.
27	func (s Skill) Name() string { return s.Frontmatter.Name }
28	
29	// Description returns the skill's frontmatter description.
30	func (s Skill) Description() string { return s.Frontmatter.Description }
31	
32	// Catalog is an immutable collection of discovered skills.
33	type Catalog struct {
34		skills []Skill
35		byName map[string]int
36	}
37	
38	// NewCatalog builds a Catalog from a slice of skills, deduplicating by name
39	// (last write wins) and sorting by name for deterministic iteration.
40	func NewCatalog(skills []Skill) *Catalog {
41		c := &Catalog{byName: make(map[string]int, len(skills))}
42		for _, s := range skills {
43			if i, ok := c.byName[s.Name()]; ok {
44				c.skills[i] = s
45				continue
46			}
47			c.byName[s.Name()] = len(c.skills)
48			c.skills = append(c.skills, s)
49		}
50		sort.SliceStable(c.skills, func(i, j int) bool {
51			return c.skills[i].Name() < c.skills[j].Name()
52		})
53		c.byName = make(map[string]int, len(c.skills))
54		for i, s := range c.skills {
55			c.byName[s.Name()] = i
56		}
57		return c
58	}
59	
60	// Len returns the number of skills in the catalog.
61	func (c *Catalog) Len() int {
62		if c == nil {
63			return 0
64		}
65		return len(c.skills)
66	}
67	
68	// Skills returns the catalog's skills sorted by name. The returned slice is
69	// a copy and may be safely retained by the caller.
70	func (c *Catalog) Skills() []Skill {
71		if c == nil {
72			return nil
73		}
74		out := make([]Skill, len(c.skills))
75		copy(out, c.skills)
76		return out
77	}
78	
79	// Names returns the skill names sorted in catalog order.
80	func (c *Catalog) Names() []string {
81		if c == nil {
82			return nil
83		}
84		out := make([]string, len(c.skills))
85		for i, s := range c.skills {
86			out[i] = s.Name()
87		}
88		return out
89	}
90	
91	// ByName returns the skill with the given name, or nil if absent.
92	func (c *Catalog) ByName(name string) *Skill {
93		if c == nil {
94			return nil
95		}
96		i, ok := c.byName[name]
97		if !ok {
98			return nil
99		}
100		s := c.skills[i]
101		return &s
102	}
103	
104	// LoadBody reads and returns the raw markdown body of the named skill —
105	// everything after the closing `---` line of the frontmatter. The file is
106	// re-opened on each call; the body is not cached.
107	func (c *Catalog) LoadBody(name string) (string, error) {
108		s := c.ByName(name)
109		if s == nil {
110			return "", fmt.Errorf("skill: unknown skill %q", name)
111		}
112		data, err := safefs.ReadFile(s.Path)
113		if err != nil {
114			return "", fmt.Errorf("skill: read %s: %w", s.Path, err)
115		}
116		if s.BodyOffset > int64(len(data)) {
117			return "", fmt.Errorf("skill: body offset %d past file length %d for %s", s.BodyOffset, len(data), s.Path)
118		}
119		return string(data[s.BodyOffset:]), nil
120	}
121	
122	// ScanDir walks dir for `SKILL.md` files, parsing frontmatter from each.
123	// A non-existent or empty dir returns an empty catalog and a nil error,
124	// allowing callers to opt in to skill discovery without branching.
125	//
126	// Files with missing/invalid frontmatter are skipped and recorded in the
127	// returned warnings slice; they do not abort the scan.
128	func ScanDir(dir string) (*Catalog, []string, error) {
129		if dir == "" {
130			return NewCatalog(nil), nil, nil
131		}
132		info, err := os.Stat(dir)
133		if err != nil {
134			if errors.Is(err, fs.ErrNotExist) {
135				return NewCatalog(nil), nil, nil
136			}
137			return nil, nil, fmt.Errorf("skill: stat %s: %w", dir, err)
138		}
139		if !info.IsDir() {
140			return nil, nil, fmt.Errorf("skill: %s is not a directory", dir)
141		}
142	
143		var skills []Skill
144		var warnings []string
145		walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
146			if err != nil {
147				warnings = append(warnings, fmt.Sprintf("walk %s: %v", path, err))
148				if d != nil && d.IsDir() {
149					return fs.SkipDir
150				}
151				return nil
152			}
153			if d.IsDir() {
154				return nil
155			}
156			if !strings.EqualFold(d.Name(), "SKILL.md") {
157				return nil
158			}
159			s, err := loadSkill(path)
160			if err != nil {
161				warnings = append(warnings, fmt.Sprintf("%s: %v", path, err))
162				return nil
163			}
164			skills = append(skills, s)
165			return nil
166		})
167		if walkErr != nil {
168			return nil, warnings, fmt.Errorf("skill: walk %s: %w", dir, walkErr)
169		}
170		return NewCatalog(skills), warnings, nil
171	}
172	
173	// loadSkill opens path, parses its frontmatter, and validates required fields.
174	// The body is not read.
175	func loadSkill(path string) (Skill, error) {
176		// #nosec G304 -- callers operate on user-selected skill directories.
177		f, err := os.Open(path)
178		if err != nil {
179			return Skill{}, fmt.Errorf("open: %w", err)
180		}
181		defer func() { _ = f.Close() }()
182	
183		fm, off, err := ParseFrontmatter(f)
184		if err != nil {
185			return Skill{}, err
186		}
187		if err := fm.Validate(); err != nil {
188			return Skill{}, err
189		}
190		abs, err := filepath.Abs(path)
191		if err != nil {
192			abs = path
193		}
194		return Skill{Path: abs, Frontmatter: fm, BodyOffset: off}, nil
195	}
