12	// LoadSkillTool exposes a *Catalog to the agent loop as the `load_skill`
13	// tool. The tool returns the raw markdown body of the named skill on
14	// demand, supporting the progressive-disclosure pattern: only the
15	// frontmatter summary is in the system prompt; full instructions are
16	// loaded lazily.
17	type LoadSkillTool struct {
18		Catalog *Catalog
19	}
20	
21	// compile-time assertion that LoadSkillTool implements agent.Tool.
22	var _ agent.Tool = (*LoadSkillTool)(nil)
23	
24	// Name returns the tool identifier.
25	func (t *LoadSkillTool) Name() string { return "load_skill" }
26	
27	// Description returns the LLM-facing description.
28	func (t *LoadSkillTool) Description() string {
29		return "Load the full instructions for a named skill. Returns the complete SKILL.md body as markdown."
30	}
31	
32	// Schema returns the JSON schema for the tool's parameters.
33	func (t *LoadSkillTool) Schema() json.RawMessage {
34		return json.RawMessage(`{
35			"type": "object",
36			"properties": {
37				"skill_name": {"type": "string", "description": "Name of the skill to load (matches the frontmatter \"name\" field)."}
38			},
39			"required": ["skill_name"]
40		}`)
41	}
42	
43	// Parallel reports that load_skill is safe to run concurrently — it only
44	// reads files.
45	func (t *LoadSkillTool) Parallel() bool { return true }
46	
47	type loadSkillParams struct {
48		SkillName string `json:"skill_name"`
49	}
50	
51	// Execute returns the markdown body of the named skill, or an error
52	// listing the available names when the requested name is unknown.
53	func (t *LoadSkillTool) Execute(_ context.Context, params json.RawMessage) (string, error) {
54		var p loadSkillParams
55		if err := json.Unmarshal(params, &p); err != nil {
56			return "", fmt.Errorf("load_skill: invalid params: %w", err)
57		}
58		if p.SkillName == "" {
59			return "", fmt.Errorf("load_skill: skill_name is required")
60		}
61		if t.Catalog == nil || t.Catalog.Len() == 0 {
62			return "", fmt.Errorf("load_skill: no skills are configured")
63		}
64		if t.Catalog.ByName(p.SkillName) == nil {
65			return "", fmt.Errorf("load_skill: skill %q not found; available: %s", p.SkillName, strings.Join(t.Catalog.Names(), ", "))
66		}
67		body, err := t.Catalog.LoadBody(p.SkillName)
68		if err != nil {
69			return "", fmt.Errorf("load_skill: %w", err)
70		}
71		return body, nil
72	}
