109	// Build assembles and returns the final system prompt string.
110	func (b *Builder) Build() string {
111		var sections []string
112	
113		// 1. Base prompt
114		if b.base != "" {
115			sections = append(sections, b.base)
116		}
117	
118		// 2. Tools section
119		if len(b.tools) > 0 {
120			var toolLines []string
121			for _, t := range b.tools {
122				toolLines = append(toolLines, fmt.Sprintf("- %s: %s", t.Name(), t.Description()))
123			}
124			sections = append(sections, "# Tools\n"+strings.Join(toolLines, "\n"))
125		}
126	
127		// 2b. Available skills (catalog already iterates in sorted order).
128		if b.skills != nil && b.skills.Len() > 0 {
129			var lines []string
130			lines = append(lines, "# Available Skills", "")
131			for _, s := range b.skills.Skills() {
132				lines = append(lines, fmt.Sprintf("- %s: %s", s.Name(), s.Description()))
133			}
134			lines = append(lines, "", "Call the load_skill tool with a skill name to load its full instructions.")
135			sections = append(sections, strings.Join(lines, "\n"))
136		}
137	
138		// 3. Guidelines
139		if len(b.guidelines) > 0 {
140			var guideLines []string
141			for _, g := range b.guidelines {
142				guideLines = append(guideLines, "- "+g)
143			}
144			sections = append(sections, "Guidelines:\n"+strings.Join(guideLines, "\n"))
145		}
146	
147		// 4. Named sections (caller-injected, e.g. DDx workflow rules)
148		for _, s := range b.sections {
149			sections = append(sections, fmt.Sprintf("# %s\n\n%s", s.name, s.body))
150		}
151	
152		// 5. Append text
153		if b.appendText != "" {
154			sections = append(sections, b.appendText)
155		}
156	
157		// 7. Project context files
158		if len(b.contextFiles) > 0 {
159			var contextParts []string
160			contextParts = append(contextParts, "# Project Context\n\nProject-specific instructions and guidelines:")
161			// Sort context files by path for stable output
162			sortedFiles := make([]ContextFile, len(b.contextFiles))
163			copy(sortedFiles, b.contextFiles)
164			sort.Slice(sortedFiles, func(i, j int) bool {
165				return sortedFiles[i].Path < sortedFiles[j].Path
166			})
167			for _, cf := range sortedFiles {
168				contextParts = append(contextParts, fmt.Sprintf("## %s\n\n%s", cf.Path, cf.Content))
169			}
170			sections = append(sections, strings.Join(contextParts, "\n\n"))
171		}
172	
173		// 8. Dynamic context
174		date := b.date
175		if date == "" {
176			date = time.Now().Format("2006-01-02")
177		}
178		dynamic := fmt.Sprintf("Current date: %s", date)
179		if b.workDir != "" {
180			dynamic += fmt.Sprintf("\nCurrent working directory: %s", b.workDir)
181		}
182		// Sort metadata keys for stable output
183		metaKeys := make([]string, 0, len(b.metadata))
184		for k := range b.metadata {
185			metaKeys = append(metaKeys, k)
186		}
187		sort.Strings(metaKeys)
188		for _, k := range metaKeys {
189			dynamic += fmt.Sprintf("\n%s: %s", k, b.metadata[k])
190		}
191		sections = append(sections, dynamic)
192	
193		return strings.Join(sections, "\n\n")
194	}
