69	// Chat looks up a recorded response matching the messages. It checks inline
70	// responses first, then falls back to file-based dictionary lookup by hash.
71	func (p *Provider) Chat(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (agent.Response, error) {
72		prompt := extractPromptText(messages)
73	
74		// Check inline responses first (pattern-based matching).
75		for _, ir := range p.cfg.InlineResponses {
76			if matchPattern(ir.PromptMatch, prompt) {
77				if ir.DelayMS > 0 {
78					sleepWithContext(ctx, ir.DelayMS)
79				}
80				return ir.Response, nil
81			}
82		}
83	
84		// Fall back to file-based dictionary lookup.
85		if p.cfg.DictDir == "" {
86			return agent.Response{}, fmt.Errorf("virtual: no matching inline response and no dictionary directory configured")
87		}
88	
89		normalized := NormalizePrompt(prompt, p.cfg.NormalizePatterns)
90		hash := PromptHash(normalized)
91		path := filepath.Join(p.cfg.DictDir, hash+".json")
92	
93		data, err := safefs.ReadFile(path)
94		if os.IsNotExist(err) {
95			return agent.Response{}, fmt.Errorf("virtual: no recorded response for prompt (hash %s, dir %s)", hash, p.cfg.DictDir)
96		}
97		if err != nil {
98			return agent.Response{}, fmt.Errorf("virtual: reading dictionary entry: %w", err)
99		}
100	
101		var entry Entry
102		if err := json.Unmarshal(data, &entry); err != nil {
103			return agent.Response{}, fmt.Errorf("virtual: parsing dictionary entry %s: %w", path, err)
104		}
105	
106		if entry.DelayMS > 0 {
107			sleepWithContext(ctx, entry.DelayMS)
108		}
109	
110		return entry.Response, nil
111	}
