118	// RecordEntry saves a message→response pair to the dictionary directory.
119	func RecordEntry(dictDir string, messages []agent.Message, response agent.Response, patterns []NormalizePattern) error {
120		if err := safefs.MkdirAll(dictDir, 0o750); err != nil {
121			return fmt.Errorf("virtual: creating dictionary dir: %w", err)
122		}
123	
124		prompt := extractPromptText(messages)
125		normalized := NormalizePrompt(prompt, patterns)
126		hash := PromptHash(normalized)
127	
128		entry := Entry{
129			PromptHash: hash,
130			Messages:   messages,
131			Response:   response,
132			RecordedAt: time.Now().UTC().Format(time.RFC3339),
133		}
134	
135		data, err := json.MarshalIndent(entry, "", "  ")
136		if err != nil {
