147	// PromptHash computes a truncated SHA-256 hash of a prompt string.
148	// Returns 16 hex characters (64 bits).
149	func PromptHash(prompt string) string {
150		h := sha256.Sum256([]byte(prompt))
151		return hex.EncodeToString(h[:8])
152	}
153	
154	// NormalizePrompt applies regex→replacement patterns before hashing.
155	// This allows prompts with dynamic content (temp paths, timestamps, IDs)
156	// to produce stable hashes across runs.
157	func NormalizePrompt(prompt string, patterns []NormalizePattern) string {
158		for _, p := range patterns {
159			re, err := regexp.Compile(p.Pattern)
160			if err != nil {
161				continue
162			}
163			prompt = re.ReplaceAllString(prompt, p.Replace)
164		}
165		return prompt
166	}
167	
168	// extractPromptText concatenates all user message content for matching/hashing.
169	func extractPromptText(messages []agent.Message) string {
170		var parts []string
171		for _, m := range messages {
172			if m.Role == agent.RoleUser {
173				parts = append(parts, m.Content)
174			}
175		}
176		return strings.Join(parts, "\n")
177	}
178	
179	// matchPattern checks if prompt matches a pattern. Patterns wrapped in /.../ are
180	// treated as regex; otherwise substring matching is used.
181	func matchPattern(pattern, prompt string) bool {
182		if len(pattern) >= 2 && pattern[0] == '/' && pattern[len(pattern)-1] == '/' {
183			re, err := regexp.Compile(pattern[1 : len(pattern)-1])
184			if err != nil {
185				return false
186			}
187			return re.MatchString(prompt)
188		}
189		return strings.Contains(prompt, pattern)
190	}
